best[(Gstart,Bstart)]=0
sols=[]
while q:
    g,b,d,acts=q.popleft()
    if d>30: continue
    if b==Bgoal and g==Ggoal:
        sols.append((d,acts)); continue
    gc=sq_cells(*g); bc=plus_cells(*b)
    for name,(dr,dc) in dirs.items():
        ng=(g[0]+dr,g[1]+dc)
        ngc=sq_cells(*ng)
