        if ngc & A: continue
        if ngc & bc:
            # pushing B? requires contact along press axis: B occupies the cell the green wants
            # determine if B is adjacent in direction d: check the leading edge
            # leading cells of green in direction d
            lead = {(g[0]+ (2 if dr==1 else (0 if dr==-1 else i)), g[1]+(2 if dc==1 else (0 if dc==-1 else j))) for i in range(3) for j in range(3)}
            # actually compute contact: cells of green adjacent toward d
            cont = {(g[0]+dr+ (0 if dr else i), g[1]+dc+(0 if dc else j)) for i in range(3) for j in range(3)}
            if dr: cont={(g[0]+(2 if dr==1 else 0)+i, g[1]+j) for i in range(0,3) for j in range(3)} if False else {(g[0]+(2 if dr==1 else 0)+i, g[1]+j) for i in range(1) for j in range(3)}
            if dc: cont={(g[0]+i, g[1]+(2 if dc==1 else 0)+j) for i in range(3) for j in range(1)}
            if not (cont & bc): continue
            # B flies 15 px in direction d
            nb=(b[0]+5*dr, b[1]+5*dc)
            nbc=plus_cells(*nb)
            if not onfloor(nbc): continue
            if nbc & A: continue
            # green moves 3 into vacated space
            pass
        else:
            nb=b; nbc=bc
