NEXT={('M',2):('p',3),('p',3):('Y',4)}
def sim(objs, clicks, verbose=True):
    # objs: list of dicts {tl:(r,c), size, color}
    objs=[dict(o) for o in objs]
    for i,cl in enumerate(clicks):
        inr=[o for o in objs if rng(o,cl)<=8.05]
        dots=[o for o in inr if o['size']==1]; sq=[o for o in inr if o['size']>1]
        if verbose: print(' ',i+1,cl,'inrange',[(o['color'],o['size'],o['tl'],round(rng(o,cl),2)) for o in inr])
        if dots and sq: return ('FATAL',objs)
        if len(dots)>=2:
            for o in dots: objs.remove(o)
            objs.append({'tl':(cl[0]-1,cl[1]-1),'size':2,'color':'M'})
        elif len(sq)==2:
            if sq[0]['color']!=sq[1]['color'] or sq[0]['size']!=sq[1]['size']: return ('UNKNOWN2SQ',objs)
            nxt=NEXT.get((sq[0]['color'],sq[0]['size']))
            if not nxt: return ('NOSUCHMERGE',objs)
            for o in sq: objs.remove(o)
            objs.append({'tl':(cl[0]-1,cl[1]-1),'size':nxt[1],'color':nxt[0]})
        elif len(sq)==1:
            sq[0]['tl']=(cl[0]-1,cl[1]-1)
        elif len(dots)==1: pass
        else: return ('NOOP',objs)
    return ('ok',objs)
