def solve_jumps(state, cells):
    from collections import deque
    DIRS=[(0,1),(0,-1),(1,0),(-1,0)]
    def mv(s):
        out=[]
        for a in s:
            for d in DIRS:
                bb_=(a[0]+d[0],a[1]+d[1]); c=(a[0]+2*d[0],a[1]+2*d[1])
                if bb_ in s and c in cells and c not in s: out.append((a,bb_,c))
        return out
    start=frozenset(state)
    if len(start)==1: return []
    seen={start}; q=deque([(start,[])])
    while q:
        s,path=q.popleft()
        for m in mv(s):
            ns=frozenset((s-{m[0],m[1]})|{m[2]})
            if ns in seen: continue
            p=path+[m]
            if len(ns)==1: return p
            seen.add(ns); q.append((ns,p))
    return None

