                rr=min(range(len(rs)),key=lambda i:abs(rs[i]-r)); cc=min(range(len(cs)),key=lambda i:abs(cs[i]-c))
                out.add((k,rr,cc))
    return out

def play(reg_key, maxjumps=8):
    log=[]
    for it in range(maxjumps):
        regions = board(current_frame)
        reg = regions[reg_key]
        if len(reg['pluses'])<=1:
            log.append('region %d already %d plus(es)'%(reg_key,len(reg['pluses']))); break
        sol = solve_jumps(reg['pluses'], reg['cells'])
        if not sol: log.append('no solution for %s'%sorted(reg['pluses'])); break
        a,bx,c = sol[0]
        sr,sc = center_in(reg,a); cr,cc = center_in(reg,c)
        action([{'action':'MOUSE','row':sr,'col':sc}])
        mk = marker_cells(current_frame, regions)
        if (reg_key,c[0],c[1]) not in mk:
            log.append('sel %s->%s MARKERS %s MISSING'%(a,c,sorted(mk))); break
        res = action([{'action':'MOUSE','row':cr,'col':cc}])
        done = {k:v for k,v in res.items() if k in ('level_completed','game_over','run_complete','done')}
        log.append('jump %s over %s -> %s %s'%(a,bx,c,done))
        if done.get('level_completed') or done.get('run_complete') or done.get('game_over'): break
    return log

