def cshape(f):
    aa=f.ascii.split('\n')
    pts=[(r,c) for r in range(3,31) for c in range(2,31) if aa[r][c]=='c']
    if not pts: return None
    r0=min(p[0] for p in pts); c0=min(p[1] for p in pts)
    rel=sorted((r-r0,c-c0) for r,c in pts)
    return (r0,c0,len(pts),''.join(f'{r},{c};' for r,c in rel))
fr=last_animation_frames
