def glyph_map(frame):
    seg = frame.segmentation
    nodes = seg['nodes']
    # find colored boxes (S or P) of size ~7x7 in top region (rows<33) and strips
    out=[]
    for n in nodes:
        if n['color'] in ('S','P') and n['pixels']>15:
            b=n['boundary']
            r0=min(p[0] for p in b); r1=max(p[0] for p in b)
            c0=min(p[1] for p in b); c1=max(p[1] for p in b)
            out.append((n['id'],n['color'],r0,c0,r1,c1,n['children']))
    return nodes, out

