def norm(mm):
        # trim all-dot rows/cols
        rows=[r for r in mm]
        while rows and all(c=='.' for c in rows[0]): rows.pop(0)
        while rows and all(c=='.' for c in rows[-1]): rows.pop()
        cols=[j for j in range(len(rows[0])) if any(r[j]=='#' for r in rows)]
        if not cols: return ['']
        out=[''.join(r[j] for j in cols) for r in rows]
        return out

def pathcells(c,d):
    mid=(c[0]+(d[0]-c[0])//2,c[1]+(d[1]-c[1])//2)
    return [mid,d]

def ocells(o0,o1):
